const fs = require('fs-extra');
const path = require('path');

const outputFileName = "LuaDefines.lua"

function buildContent(config) {
    var content = ""
    for (var path in config) {
        var item = config[path]
        if (item.HasClassCtor) {
            content += `local ctor = require(${path})\n`
            content += `export type ${item.Key} = typeof(ctor.new())\n`
        }
        else if (item.HasTypeDefine) {
            content += `local source = require(${path})\n`
            content += `export type ${item.Key} = source.Type\n`
        } else {
            content += `export type ${item.Key} = typeof(require(${path}))\n`
        }
        content += "\n"
    }
    return content
}

function gen(config, outputPath) {
    fs.ensureDirSync(outputPath);
    var content = buildContent(config)
    fs.writeFileSync(path.join(outputPath, outputFileName), content);
    console.log(`write file ${outputPath}`)
}


module.exports = gen;